TOL = 0.25
VOL_REL_TOL = 0.015


def result_root():
    for key in ("EVAL_OUTPUT_ROOT", "OUTPUT_ROOT"):
        value = os.environ.get(key)
        if value:
            return Path(value)
    return Path("/home/user/Desktop")


def report(payload, rc):
    """Keep the repository's exact_match contract while retaining opt-in diagnostics."""
    if os.environ.get("REVERSE_EVAL_DEBUG"):
        print(json.dumps(payload, ensure_ascii=False, sort_keys=True), file=sys.stderr)
    print("True" if rc == 0 else "False")
    return rc


def inside(shape, point):
    try:
        return bool(shape.isInside(tuple(point), 1e-5))
    except Exception:
        return False


def main():
    path = result_root() / "result.step"
    if not path.exists():
        return report({"valid": False, "score": 0.0, "errors": [f"missing {path}"]}, 1)
    errors = []
    warnings = []
    try:
        imported = cq.importers.importStep(str(path))
        solids = imported.solids().vals()
    except Exception as exc:
        return report({"valid": False, "score": 0.0, "errors": [f"STEP parse failed: {exc}"]}, 1)
    if len(solids) != 1:
        errors.append(f"expected exactly one connected solid, found {len(solids)}")
        shape = solids[0] if solids else None
    else:
        shape = solids[0]
    if shape is None:
        errors.append("no solid geometry")
    else:
        try:
            if not shape.isValid():
                errors.append("B-rep is invalid")
        except Exception as exc:
            errors.append(f"validity check failed: {exc}")
        bb = shape.BoundingBox()
        actual = [float(bb.xlen), float(bb.ylen), float(bb.zlen)]
        target = SPEC["bbox_span"]
        for axis, a, t in zip("XYZ", actual, target):
            if abs(a - t) > TOL:
                errors.append(f"bbox {axis} span {a:.4f} != {t:.4f} ± {TOL}")
        vol = float(shape.Volume())
        if abs(vol - SPEC["volume"]) > max(0.5, SPEC["volume"] * VOL_REL_TOL):
            errors.append(f"volume {vol:.4f} != {SPEC['volume']:.4f}")
        area = float(shape.Area())
        if abs(area - SPEC["surface_area"]) > max(0.5, SPEC["surface_area"] * 0.02):
            errors.append(f"surface area {area:.4f} != {SPEC['surface_area']:.4f}")
        for p in SPEC.get("solid_probes", []):
            if not inside(shape, p):
                errors.append(f"material probe unexpectedly empty at {p}")
        for p in SPEC.get("empty_probes", []):
            if inside(shape, p):
                errors.append(f"void probe unexpectedly occupied at {p}")
        mismatch_count = 0
        for x, y, z, expected in SPEC.get("occupancy_samples", []):
            if inside(shape, [x, y, z]) != bool(expected):
                mismatch_count += 1
                if mismatch_count <= 8:
                    errors.append(f"occupancy mismatch at [{x:.3f}, {y:.3f}, {z:.3f}]")
        if mismatch_count > 8:
            errors.append(f"{mismatch_count - 8} additional occupancy mismatches")
    score = 1.0 if not errors else 0.0
    out = {"valid": not errors, "score": score, "errors": errors, "warnings": warnings}
    return report(out, 0 if not errors else 1)


if __name__ == "__main__":
    raise SystemExit(main())
